select *, lag(revenue) over w_recent prev_revenue, lead(revenue) over w_recent next_revenue, lead(units) over w_recent next_units, row_number() over w_recent row_seq, avg(units) over w_hist units_avg_5_prior from store_sales window w_recent as (partition by product_id order by units, id), w_hist as (partition by store_id, product_id order by sale_date, id rows between 5 preceding and 1 preceding);
